import Image from "next/image";

interface QRImageProps {
  data?: string;
  svg?: string;
  size?: number;
  className?: string;
}

/** Displays the QR generated by the backend without sending card IDs elsewhere. */
export default function QRImage({ data, svg, size = 200, className }: QRImageProps) {
  if (!svg) {
    return (
      <div
        className={`flex items-center justify-center rounded border border-dashed border-slate-300 bg-white px-2 text-center text-[0.6rem] leading-tight text-slate-500 ${className || ""}`}
        style={{ width: size, height: size }}
        role="img"
        aria-label="QR code will be added when this card is generated"
      >
        QR generated with card
      </div>
    );
  }

  return (
    <Image
      src={`data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`}
      width={size}
      height={size}
      alt={data ? `Invitation QR code for ${data}` : "Invitation QR code"}
      className={className}
      unoptimized
      loading="lazy"
    />
  );
}
